/** Partner laboratories and imaging centres — GET /api/v1/diagnostic-partners (who may call: holders of diagnostics.setup.manage or diagnostics.quality.view or lab.sendout.manage or imaging.order.update or lab.test.manage). */
export function listPartners(query?: { services?: "Lab" | "Imaging" | null; active_only?: boolean }): Promise<PartnerOut[]> {
  return api<PartnerOut[]>("GET", withQuery(`/diagnostic-partners`, query), undefined);
}

/** Send an examination to a partner centre — POST /api/v1/imaging/orders/{order_id}/outsource (who may call: holders of imaging.order.update). */
export function outsource(order_id: number, body: OutsourceIn): Promise<ImagingOrderOut> {
  return api<ImagingOrderOut>("POST", `/imaging/orders/${order_id}/outsource`, body, { idempotent: true });
}

/** Enter the partner centre's report — POST /api/v1/imaging/orders/{order_id}/external-report (who may call: holders of imaging.order.update). */
export function externalReport(order_id: number, body: ExternalReportIn): Promise<ImagingOrderOut> {
  return api<ImagingOrderOut>("POST", `/imaging/orders/${order_id}/external-report`, body, { idempotent: true });
}

/** Radiographer worklist (STAT first, then by due time) — GET /api/v1/imaging/worklist (who may call: holders of imaging.order.update). */
export function worklistImaging(query?: { status?: "Ordered" | "Scheduled" | "InProgress" | "Completed" | null; modality?: "XRay" | "MRI" | "CT" | "Ultrasound" | "Doppler" | "Mammography" | "Fluoroscopy" | "Other" | null }): Promise<ImagingWorklistItemOut[]> {
  return api<ImagingWorklistItemOut[]>("GET", withQuery(`/imaging/worklist`, query), undefined);
}

/** The critical imaging findings list — GET /api/v1/critical-imaging-findings (who may call: holders of imaging.report.enter or diagnostics.setup.manage or diagnostics.critical.view). */
export function listFindings(query?: { active_only?: boolean }): Promise<CriticalFindingOut[]> {
  return api<CriticalFindingOut[]>("GET", withQuery(`/critical-imaging-findings`, query), undefined);
}
